  "transcript": {
    "segments": [
      {
        "start": 0,
        "end": 1.24,
        "text": "普通的平面產品圖"
      },
      {
        "start": 1.24,
        "end": 3.6,
        "text": "也能做成立體感失誤的三敵創意食品"
      },
      {
        "start": 3.6,
        "end": 4.92,
        "text": "整個過程幣不負責"
      },
      {
        "start": 4.92,
        "end": 5.72,
        "text": "給你三十秒"
      },
      {
        "start": 5.72,
        "end": 7.76,
        "text": "但你從一張圖片一步步做到食品"
      },
      {
        "start": 7.76,
        "end": 9.36,
        "text": "上傳準備好的產品圓圖"
      },
      {
        "start": 9.36,
        "end": 10.92,
        "text": "然後複製對應的提示值"
      },
      {
        "start": 10.92,
        "end": 11.88,
        "text": "並點擊聲稱"
      },
      {
        "start": 11.88,
        "end": 13.24,
        "text": "AI就會根據圓圖"
      },
      {
        "start": 13.24,
        "end": 14.92,
        "text": "聲稱對應產品數標圖"
      },
      {
        "start": 14.92,
        "end": 15.68,
        "text": "聲稱之後"
      },
      {
        "start": 15.68,
        "end": 16.64,
        "text": "從裡面挑選一專"
      },
      {
        "start": 16.64,
        "end": 18.24,
        "text": "自己比較滿意的爆聲下來"
      },
      {
        "start": 18.24,
        "end": 19.32,
        "text": "接下來把產品圓圖"
      },
      {
        "start": 19.32,
        "end": 21.48,
        "text": "和剛剛聲稱的數標圖一起上傳"
      },
      {
        "start": 21.48,
        "end": 22.84,
        "text": "再配合對應提示值"
      },
      {
        "start": 22.84,
        "end": 24.24,
        "text": "大概聲稱立體效果"
      },
      {
        "start": 24.24,
        "end": 25.92,
        "text": "這樣近代平面產品圖"
      },
      {
        "start": 25.92,
        "end": 27.68,
        "text": "就完成了第一次世界轉換"
      },
      {
        "start": 27.68,
        "end": 29.76,
        "text": "最後一步切換了4瓶聲稱功能"
      },
      {
        "start": 29.76,
        "end": 31.4,
        "text": "再把前面得到的兩張圖片"
      },
      {
        "start": 31.4,
        "end": 33.04,
        "text": "順便設置為首尾燈"
      },
      {
        "start": 33.04,
        "end": 34.84,
        "text": "再輸入對應的4瓶提示值"
      },
      {
        "start": 34.84,
        "end": 36.48,
        "text": "點擊聲稱收藏學校"
      },
      {
        "start": 36.48,
        "end": 39.04,
        "text": "AI會根據兩張畫面之間的變化關係"
      },
      {
        "start": 39.04,
        "end": 39.92,
        "text": "自動聲稱中"
      },
      {
        "start": 39.92,
        "end": 41.6,
        "text": "平面到立體的動態過度"
      },
      {
        "start": 41.6,
        "end": 42.72,
        "text": "因夠完整的平面轉"
      },
      {
        "start": 42.72,
        "end": 44.24,
        "text": "立體創意食品就做好了"
      },
      {
        "start": 44.24,
        "end": 45.24,
        "text": "最後爆成4瓶"
      },
      {
        "start": 45.24,
        "end": 47.04,
        "text": "來看一下最終的成績效果"
      }
